-- 1934 (2026-11-26): federation principles sweep — every FIFA association searched for its own published principles of play
-- (owner 11/26 "we should have every federation principles" · "get it all in"). Built by scripts/taxonomy/fed_principles_to_sql.py
-- from the research agents' JSON (UEFA west, Americas, Asia + Oceania, Africa; UEFA east follows). All verified = false.
CREATE TABLE IF NOT EXISTS game_federations (
    id            serial PRIMARY KEY,
    name          text NOT NULL UNIQUE,
    country       text NOT NULL DEFAULT '',
    confederation text NOT NULL,
    principles_status text NOT NULL CHECK (principles_status IN ('found', 'known', 'not_published', 'not_searched')),
    source_id     integer REFERENCES game_sources(id),
    url           text,
    note          text NOT NULL DEFAULT ''
);
CREATE TEMP TABLE t_terms (src text, term text, lang text, lvl text, side text, canon text, rel text) ON COMMIT DROP;
SELECT s.id, t.term, t.lang, t.lvl, t.side, coalesce(s.url, ''), false FROM t_terms t JOIN game_sources s ON s.code = t.src
ON CONFLICT (source_id, term) DO NOTHING;
SELECT pt.id, p.id, t.rel FROM t_terms t JOIN game_sources s ON s.code = t.src
  JOIN game_source_principles pt ON pt.source_id = s.id AND pt.term = t.term
  JOIN game_play_principles p ON p.code = t.canon
ON CONFLICT DO NOTHING;
-- A new common-ground row IS the term that made it: 'same', not 'overlaps'.
UPDATE game_common_principle_links l SET relation = 'same' FROM game_play_principles p WHERE p.id = l.principle_id AND p.code LIKE 'x-%';
-- Counter-attack on regain = counter-attack.
UPDATE game_common_principle_links l SET principle_id = (SELECT id FROM game_play_principles WHERE code = 'x-counter-attack')
 WHERE principle_id = (SELECT id FROM game_play_principles WHERE code = 'x-counter-attack-on-regain')
   AND NOT EXISTS (SELECT 1 FROM game_common_principle_links k WHERE k.term_id = l.term_id AND k.principle_id = (SELECT id FROM game_play_principles WHERE code = 'x-counter-attack'));
DELETE FROM game_play_principles p WHERE code = 'x-counter-attack-on-regain'
   AND NOT EXISTS (SELECT 1 FROM game_common_principle_links l WHERE l.principle_id = p.id);
