INSERT INTO game_federations (name, country, confederation, principles_status, url, note, source_id) VALUES ('Japan Football Association (JFA)', 'Japan', 'AFC', 'found', 'https://www.jfa.jp/coach/books_correction.pdf', 'Official correction notice: pre-2022 = Wade 1968 4 attack + 4 defence (old 遅らせる covered press+delay, old 突破 covered support; full old names not printed); from April 2022 = England-style 5+5 under 攻撃(In Possession)/守備(Out of Possession).', (SELECT id FROM game_sources WHERE code = 'jfa')) ON CONFLICT (name) DO UPDATE SET principles_status = EXCLUDED.principles_status, url = EXCLUDED.url, note = EXCLUDED.note, source_id = EXCLUDED.source_id;
INSERT INTO game_federations (name, country, confederation, principles_status, url, note, source_id) VALUES ('Football Australia', 'Australia', 'AFC', 'known', 'https://de.slideshare.net/PedMenCoach/the-roadmap-to-international-success-ffa-national-curriculum-2013', 'Known: four main moments + team tasks (building up / attacking & scoring / disturbing / defending); no newer official wording found.', (SELECT id FROM game_sources WHERE code = 'football-australia')) ON CONFLICT (name) DO UPDATE SET principles_status = EXCLUDED.principles_status, url = EXCLUDED.url, note = EXCLUDED.note, source_id = EXCLUDED.source_id;
INSERT INTO game_sources (code, kind, title, url, verified) VALUES ('fed-indonesia', 'federation', 'PSSI (Football Association of Indonesia) — Kurikulum Pembinaan Sepakbola Indonesia (Filanesia), PSSI 2017 - as quoted by theses/journals — principles of play', 'https://digilib.unimed.ac.id/63076/7/8216117003_BAB_I.pdf', false) ON CONFLICT (code) DO NOTHING;
INSERT INTO game_federations (name, country, confederation, principles_status, url, note, source_id) VALUES ('PSSI (Football Association of Indonesia)', 'Indonesia', 'AFC', 'found', 'https://digilib.unimed.ac.id/63076/7/8216117003_BAB_I.pdf', 'PSSI book not found online; wording consistent across several secondary sources; learning formation 1-4-3-3; 2023 upgrade with Frank Wormuth.', (SELECT id FROM game_sources WHERE code = 'fed-indonesia')) ON CONFLICT (name) DO UPDATE SET principles_status = EXCLUDED.principles_status, url = EXCLUDED.url, note = EXCLUDED.note, source_id = EXCLUDED.source_id;
