INSERT INTO game_sources (code, kind, title, url, verified) VALUES ('fed-tanzania', 'federation', 'Tanzania Football Federation (TFF) — Tanzania Football Federation - Football Philosophy (playing philosophy, phases of play / game model) — principles of play', 'https://tff.or.tz/wp-content/uploads/2019/08/Tanzania-Philosophy.pdf', false) ON CONFLICT (code) DO NOTHING;
INSERT INTO game_federations (name, country, confederation, principles_status, url, note, source_id) VALUES ('Tanzania Football Federation (TFF)', 'Tanzania', 'CAF', 'found', 'https://tff.or.tz/wp-content/uploads/2019/08/Tanzania-Philosophy.pdf', 'Federation PDF (2019, 67pp; live URL now 404, read via web.archive.org). Four moments + per-third phases; defend = Press-Cover-Balance and Delay-Deny-Restrict; England-DNA-style wording.', (SELECT id FROM game_sources WHERE code = 'fed-tanzania')) ON CONFLICT (name) DO UPDATE SET principles_status = EXCLUDED.principles_status, url = EXCLUDED.url, note = EXCLUDED.note, source_id = EXCLUDED.source_id;
